(function(){'use strict';var featuredProductsPromise=(window.PhucGiaTienAPI)?PhucGiaTienAPI.getFeaturedProducts(12):null;function renderFeaturedProducts(){var conveyor=document.getElementById('home-product-conveyor');var track=document.getElementById('home-product-track');if(!conveyor||!track)return;var apiCall=featuredProductsPromise||(window.PhucGiaTienAPI?PhucGiaTienAPI.getFeaturedProducts(12):null);if(!apiCall)return;apiCall.then(function(products){setTimeout(function(){if(products.length===0){track.innerHTML='<p style="color:var(--color-text-muted);padding:2rem;text-align:center">Không có sản phẩm nào.</p>';return;}try{var fragment=document.createDocumentFragment();var originalElements=[];products.forEach(function(p,i){if(typeof window.buildProductCard==='function'){var cardEl=window.buildProductCard(p,i,i<4);fragment.appendChild(cardEl);originalElements.push(cardEl);}});originalElements.forEach(function(card){var clone=card.cloneNode(true);clone.setAttribute('aria-hidden','true');clone.setAttribute('tabindex','-1');clone.querySelectorAll('a, button, input, select, textarea').forEach(function(el){el.setAttribute('tabindex','-1');});clone.addEventListener('click',function(){if(clone.dataset.slug){window.location.href='/'+clone.dataset.slug;}});var btn=clone.querySelector('.product-card__btn-cart');if(btn){btn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();if(!window.CartAPI)return;var pData=JSON.parse(this.dataset.product||'{}');if(!pData.id)return;if(pData.variants&&pData.variants.length>1){window.location.href='/'+pData.slug;return;}var v=(pData.variants&&pData.variants.length===1)?pData.variants[0]:null;var price=v?v.price:(pData.price||0);var sizeParts=[];if(v){if(v.sizeName||v.size)sizeParts.push(v.sizeName||v.size);if(v.patternName)sizeParts.push(v.patternName);if(v.colorName)sizeParts.push(v.colorName);if(v.productTypeName)sizeParts.push(v.productTypeName);if(v.materialName)sizeParts.push(v.materialName);}var sizeStr=sizeParts.join(' · ')||null;var images=(v&&v.images&&v.images.length>0)?v.images:(pData.images||[]);window.CartAPI.addItem({id:pData.id,slug:pData.slug,name:pData.name,price:price,size:sizeStr,images:images,gifts:pData.gifts||[]},1,e);});}fragment.appendChild(clone);});track.innerHTML='';track.appendChild(fragment);requestAnimationFrame(function(){requestAnimationFrame(function(){setupConveyorControls(conveyor,track,originalElements.length);if(typeof window.initScrollReveal==='function')window.initScrollReveal();});});}catch(err){track.innerHTML='<p style="color:red;padding:2rem;">Lỗi build thẻ: '+err.message+'</p>';}},150);}).catch(function(err){var t=document.getElementById('home-product-track');if(t)t.innerHTML='<p style="color:red;padding:2rem;text-align:center">Lỗi API: '+err.message+'</p>';console.error(err);});}function setupConveyorControls(conveyor,track,originalCardCount){var isDown=false;var startX;var scrollLeftStart;var isPaused=false;var isAnimating=false;var resumeTimeout=null;var autoCycleInterval=null;var slideStep=334;var trackHalfW=(originalCardCount||12)*slideStep;function snapToNearestCard(dragDistance,startScroll){if(isAnimating)return;var currentScroll=conveyor.scrollLeft;var targetIdx;var threshold=30;if(startScroll!==undefined){var startIdx=Math.round(startScroll/slideStep);if(Math.abs(dragDistance)>threshold){if(dragDistance>0){targetIdx=startIdx+1;}else{targetIdx=startIdx-1;}}else{targetIdx=startIdx;}}else{var currentIdx=currentScroll/slideStep;if(Math.abs(dragDistance)>threshold){if(dragDistance>0)targetIdx=Math.ceil(currentIdx);else targetIdx=Math.floor(currentIdx);}else{targetIdx=Math.round(currentIdx);}}var targetScroll=targetIdx*slideStep;var changeAmount=targetScroll-currentScroll;smoothScrollToTarget(changeAmount,350);}function startAutoCycle(){if(autoCycleInterval)clearInterval(autoCycleInterval);autoCycleInterval=setInterval(function(){if(!isPaused&&!isDown&&!isAnimating){scrollToIndex(1);}},8000);}startAutoCycle();conveyor.addEventListener('mouseenter',function(){isPaused=true;if(autoCycleInterval)clearInterval(autoCycleInterval);});conveyor.addEventListener('mouseleave',function(){if(!isDown){isPaused=false;startAutoCycle();}});var touchStartX=0;var touchStartY=0;var touchScrollStart=0;var isTouching=false;var isSwipeDirectionDecided=false;var isHorizontalSwipe=false;conveyor.addEventListener('touchstart',function(e){isPaused=true;isTouching=true;isSwipeDirectionDecided=false;isHorizontalSwipe=false;if(autoCycleInterval)clearInterval(autoCycleInterval);touchStartX=e.touches[0].pageX;touchStartY=e.touches[0].pageY;touchScrollStart=conveyor.scrollLeft;clearTimeout(resumeTimeout);},{passive:true});conveyor.addEventListener('touchmove',function(e){if(!isTouching)return;var currentX=e.touches[0].pageX;var currentY=e.touches[0].pageY;var diffX=currentX-touchStartX;var diffY=currentY-touchStartY;if(!isSwipeDirectionDecided){if(Math.abs(diffX)>5||Math.abs(diffY)>5){isHorizontalSwipe=Math.abs(diffX)>Math.abs(diffY);isSwipeDirectionDecided=true;}}if(isSwipeDirectionDecided&&isHorizontalSwipe){if(e.cancelable){e.preventDefault();}var walk=diffX*1.5;var newScrollLeft=touchScrollStart-walk;if(newScrollLeft>=trackHalfW){newScrollLeft-=trackHalfW;touchScrollStart-=trackHalfW;}else if(newScrollLeft<=0){newScrollLeft+=trackHalfW;touchScrollStart+=trackHalfW;}conveyor.scrollLeft=newScrollLeft;}},{passive:false});conveyor.addEventListener('touchend',function(){if(!isTouching)return;isTouching=false;var dragDistance=conveyor.scrollLeft-touchScrollStart;snapToNearestCard(dragDistance,touchScrollStart);},{passive:true});conveyor.addEventListener('mousedown',function(e){isDown=true;isPaused=true;if(autoCycleInterval)clearInterval(autoCycleInterval);startX=e.pageX-conveyor.offsetLeft;scrollLeftStart=conveyor.scrollLeft;clearTimeout(resumeTimeout);});window.addEventListener('mouseup',function(){if(!isDown)return;isDown=false;var dragDistance=conveyor.scrollLeft-scrollLeftStart;snapToNearestCard(dragDistance,scrollLeftStart);});conveyor.addEventListener('mousemove',function(e){if(!isDown)return;e.preventDefault();var x=e.pageX-conveyor.offsetLeft;var walk=(x-startX)*1.5;var newScrollLeft=scrollLeftStart-walk;if(newScrollLeft>=trackHalfW){newScrollLeft-=trackHalfW;scrollLeftStart-=trackHalfW;}else if(newScrollLeft<=0){newScrollLeft+=trackHalfW;scrollLeftStart+=trackHalfW;}conveyor.scrollLeft=newScrollLeft;});function smoothScrollToTarget(changeAmount,duration){var start=conveyor.scrollLeft;var startTime=performance.now();isAnimating=true;isPaused=true;function animateScroll(currentTime){var elapsed=currentTime-startTime;var progress=Math.min(elapsed/duration,1);var ease=progress*(2-progress);var currentPos=start+changeAmount*ease;if(currentPos>=trackHalfW){currentPos-=trackHalfW;start-=trackHalfW;}else if(currentPos<=0){currentPos+=trackHalfW;start+=trackHalfW;}conveyor.scrollLeft=currentPos;if(progress<1){requestAnimationFrame(animateScroll);}else{isAnimating=false;clearTimeout(resumeTimeout);resumeTimeout=setTimeout(function(){isPaused=false;startAutoCycle();},1500);}}requestAnimationFrame(animateScroll);}var prevBtn=document.getElementById('conveyor-prev-btn');var nextBtn=document.getElementById('conveyor-next-btn');function scrollToIndex(direction){if(isAnimating)return;startAutoCycle();var currentScroll=conveyor.scrollLeft;var currentIdx=Math.round(currentScroll/slideStep);var targetIdx=currentIdx+direction;var targetScroll=targetIdx*slideStep;var changeAmount=targetScroll-currentScroll;if(direction>0&&changeAmount<50){changeAmount+=slideStep;}else if(direction<0&&changeAmount>-50){changeAmount-=slideStep;}smoothScrollToTarget(changeAmount,500);}if(prevBtn){prevBtn.addEventListener('click',function(){scrollToIndex(-1);});}if(nextBtn){nextBtn.addEventListener('click',function(){scrollToIndex(1);});}}function initProcessSteps(){var steps=document.querySelectorAll('.process-step');steps.forEach(function(step,i){step.classList.add('reveal');step.dataset.delay=String(i*120);});}function initHeroParallax(){var heroBg=document.querySelector('.hero__bg-img');if(!heroBg)return;window.addEventListener('scroll',window.debounce(function(){var scrollY=window.scrollY;if(scrollY<window.innerHeight){heroBg.style.transform='scale(1.07) translateY('+(scrollY*0.25)+'px)';}},10),{passive:true});}function initFeatureBadges(){var badges=document.querySelectorAll('.feature-badge');badges.forEach(function(badge,i){badge.classList.add('reveal');badge.dataset.delay=String(i*100);});}function initCtaPhone(){var phoneLinks=document.querySelectorAll('.cta-banner__phone, .footer-contact-list__item--phone');phoneLinks.forEach(function(el){el.style.cursor='pointer';el.title='Nhấn để sao chép số điện thoại';el.addEventListener('click',function(){var phone=el.dataset.phone||el.textContent.trim().replace(/[^0-9+]/g,'');if(navigator.clipboard&&phone){navigator.clipboard.writeText(phone).then(function(){window.showToast('Đã sao chép: '+phone,'success');});}});});}function smoothScrollTo(targetY,duration){var startY=window.scrollY;var distance=targetY-startY;var startTime=null;function easeInOutQuart(t){return t<0.5?8*t*t*t*t:1-Math.pow(-2*t+2,4)/2;}function step(currentTime){if(!startTime)startTime=currentTime;var elapsed=currentTime-startTime;var progress=Math.min(elapsed/duration,1);var ease=easeInOutQuart(progress);window.scrollTo(0,startY+distance*ease);if(progress<1){requestAnimationFrame(step);}}requestAnimationFrame(step);}function initHeroScrollBtn(){var btn=document.getElementById('hero-scroll-btn');if(!btn)return;btn.addEventListener('click',function(){var target=document.getElementById('hero-next-section');if(!target){target=document.querySelector('.hero ~ section');}if(!target)return;var header=document.getElementById('site-header');var headerH=header?header.offsetHeight:72;var targetY=target.getBoundingClientRect().top+window.scrollY-headerH;smoothScrollTo(targetY,900);});}document.addEventListener('DOMContentLoaded',function(){renderFeaturedProducts();initProcessSteps();initHeroParallax();initFeatureBadges();initCtaPhone();initHeroScrollBtn();});})();